/// A Plus Jakarta Sans text style that scales with Dynamic Type.
struct PersonalTextStyle: Hashable {
    let postScriptName: String
    let size: CGFloat
    let lineHeight: CGFloat
    let tracking: CGFloat
    let uppercase: Bool
    let relativeTo: Font.TextStyle

    var font: Font { Font.custom(postScriptName, size: size, relativeTo: relativeTo) }

    var uiFont: UIFont {
        let base = UIFont(name: postScriptName, size: size) ?? UIFont.systemFont(ofSize: size)
        return UIFontMetrics(forTextStyle: relativeTo.personalUIKitStyle).scaledFont(for: base)
    }

    /// Extra spacing between lines so the rendered line height matches the token.
    var lineSpacing: CGFloat {
        let scale = UIFontMetrics(forTextStyle: relativeTo.personalUIKitStyle).scaledValue(for: lineHeight) / max(lineHeight, 1)
        return max(0, lineHeight * scale - uiFont.lineHeight)
    }
}

private extension Font.TextStyle {
    var personalUIKitStyle: UIFont.TextStyle {
        switch self {
        case .largeTitle: return .largeTitle
        case .title: return .title1
        case .title2: return .title2
        case .title3: return .title3
        case .headline: return .headline
        case .subheadline: return .subheadline
        case .callout: return .callout
        case .footnote: return .footnote
        case .caption: return .caption1
        case .caption2: return .caption2
        default: return .body
        }
    }
}

